[{"order":1,"type":"heading","text":"Espresso UI Testing and Idling Resources in Android (Java)"},{"order":2,"type":"paragraph","text":"Android UI testing can be challenging when dealing with asynchronous operations like network requests, database transactions, or long-running background tasks. If Espresso performs actions while the app is still busy loading data, tests become flaky and fail randomly. This tutorial explores how to use Espresso Idling Resources to synchronize your UI tests with asynchronous app states."},{"order":3,"type":"subheading","text":"Understanding the Problem: Flaky Tests"},{"order":4,"type":"paragraph","text":"By default, Espresso automatically synchronizes with the main thread, AsyncTask, and certain Android framework components. However, it is completely unaware of custom background threads, Retrofit/OkHttp calls, RxJava streams, or Coroutines. When your UI depends on data fetched from a background thread, Espresso may click or assert on a view before the data has populated, causing test failures."},{"order":5,"type":"subheading","text":"What is an Idling Resource?"},{"order":6,"type":"paragraph","text":"An Idling Resource informs Espresso when your app is busy performing background work. Espresso monitors the registered Idling Resource and pauses test execution until it transitions to an "idle" state. This eliminates the need for arbitrary Thread.sleep() calls and ensures reliable test execution."},{"order":7,"type":"subheading","text":"Step 1: Implement a Custom SimpleIdlingResource"},{"order":8,"type":"paragraph","text":"First, create a custom implementation of the IdlingResource interface. This class will maintain a boolean flag indicating whether the app is idle, alongside a callback to notify Espresso when the state changes."},{"order":9,"type":"code","text":"import androidx.test.espresso.IdlingResource;
import java.util.concurrent.atomic.AtomicBoolean;

public class SimpleIdlingResource implements IdlingResource {

    private volatile ResourceCallback resourceCallback;
    private final AtomicBoolean isIdleNow = new AtomicBoolean(true);

    @Override
    public String getName() {
        return this.getClass().getName();
    }

    @Override
    public boolean isIdleNow() {
        return isIdleNow.get();
    }

    @Override
    public void registerIdleTransitionCallback(ResourceCallback callback) {
        this.resourceCallback = callback;
    }

    public void setIdleState(boolean isIdle) {
        isIdleNow.set(isIdle);
        if (isIdle && resourceCallback != null) {
            resourceCallback.transitionToIdle();
        }
    }
}"},{"order":10,"type":"subheading","text":"Step 2: Integrate Idling Resource in Production Code"},{"order":11,"type":"paragraph","text":"To keep production code clean, expose your Idling Resource selectively or use a dependency injection framework like Dagger or Hilt. For simplicity, we can use a singleton helper class to provide the resource instance."},{"order":12,"type":"code","text":"public final class EspressoIdlingResource {
    private static final String RESOURCE = "GLOBAL";
    private static final SimpleIdlingResource idlingResource = new SimpleIdlingResource();

    public static void increment() {
        idlingResource.setIdleState(false);
    }

    public static void decrement() {
        idlingResource.setIdleState(true);
    }

    public static IdlingResource getIdlingResource() {
        return idlingResource;
    }
}"},{"order":13,"type":"subheading","text":"Step 3: Managing State During Network Calls"},{"order":14,"type":"paragraph","text":"Wrap your asynchronous operations using the increment and decrement methods. For example, before executing an API call, call increment(). Once the response is received and processed on the UI thread, call decrement()."},{"order":15,"type":"code","text":"public void fetchData() {
    EspressoIdlingResource.increment();
    // Simulating a network call or background task
    new Thread(new Runnable() {
        @Override
        public void run() {
            try {
                Thread.sleep(2000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            } finally {
                // Always decrement in a finally block to avoid deadlocks
                EspressoIdlingResource.decrement();
            }
        }
    }).start();
}"},{"order":16,"type":"subheading","text":"Step 4: Registering the Resource in Your UI Test"},{"order":17,"type":"paragraph","text":"Before running your Espresso tests, register the Idling Resource using IdlingRegistry.getInstance().register(). Always unregister it in the @After block to prevent memory leaks."},{"order":18,"type":"code","text":"import androidx.test.espresso.IdlingRegistry;
import androidx.test.ext.junit.rules.ActivityScenarioRule;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.runner.RunWith;

import static androidx.test.espresso.Espresso.onView;
import static androidx.test.espresso.action.ViewActions.click;
import static androidx.test.espresso.assertion.ViewAssertions.matches;
import static androidx.test.espresso.matcher.ViewMatchers.isDisplayed;
import static androidx.test.espresso.matcher.ViewMatchers.withId;
import static androidx.test.espresso.matcher.ViewMatchers.withText;

@RunWith(AndroidJUnit4.class)
public class MainActivityTest {

    @Rule
    public ActivityScenarioRule<MainActivity> activityRule =
            new ActivityScenarioRule<>(MainActivity.class);

    @Before
    public void registerIdlingResource() {
        IdlingRegistry.getInstance().register(EspressoIdlingResource.getIdlingResource());
    }

    @After
    public void unregisterIdlingResource() {
        IdlingRegistry.getInstance().unregister(EspressoIdlingResource.getIdlingResource());
    }

    @Test
    public void testDataLoadingAndDisplay() {
        onView(withId(R.id.button_load)).perform(click());

        // Espresso automatically waits here because the Idling Resource is busy
        onView(withId(R.id.text_result)).check(matches(withText("Data Loaded")));
    }
}"},{"order":19,"type":"subheading","text":"Best Practices for Idling Resources"},{"order":20,"type":"bullet_point","text":"Always decrement your idling resource inside a finally block to prevent tests from hanging indefinitely if an exception occurs."},{"order":21,"type":"bullet_point","text":"Never register production Idling Resources permanently if they are not needed for tests, as it adds unnecessary overhead."},{"order":22,"type":"bullet_point","text":"Consider using existing libraries like CountingIdlingResource provided by AndroidX testing utilities rather than writing custom wrappers from scratch."}]
